contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a mock token that reverts on transferFrom
        RevertingToken token = new RevertingToken();
        address from = address(0x1234);
        address[] memory tos = new address[](1);
        tos[0] = address(0x5678);
        uint v = 100;

        // Call transfer and catch revert
        bool ok;
        try c.transfer(from, address(token), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference requires the external call to succeed, so it reverts (ok == false)
